import heapq

def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None
    priority_queue = [(0, start, (start, None))]
    cost_to_reach = {start: 0}
    previous_node = {start: None}
    while priority_queue:
        current_cost, current_node, path = heapq.heappop(priority_queue)
        if current_node == goal:
            reconstructed_path = []
            while current_node is not None:
                reconstructed_path.append(current_node)
                current_node = previous_node[current_node]
            reconstructed_path.reverse()
            return reconstructed_path
        for neighbor in graph[current_node]:
            candidate_cost = current_cost + 1
            if neighbor not in cost_to_reach or candidate_cost < cost_to_reach[neighbor]:
                cost_to_reach[neighbor] = candidate_cost
                previous_node[neighbor] = current_node
                heapq.heappush(priority_queue, (candidate_cost, neighbor, path + (neighbor,)))
    return None
