        x1, y1 = a
        x2, y2 = b
        return abs((x1 - x2) ** 2 + (y1 - y2) ** 2) ** 0.5

    def a_star_search(graph, start, goal, heuristic=heuristic):
        frontier = [[start]]
        came_from = {}
        cost_so_far = {}
        frontier.append([start])
        came_from[start] = None
        cost_so_far[start] = 0
        while frontier:
            current = frontier.pop(0)
            if current[-1] == goal:
                break
            for next in graph.get(current[-1], []):
                new_cost = cost_so_far[current[-1]] + 1
                if next not in cost_so_far or new_cost < cost_so_far[next]:
                    cost_so_far[next] = new_cost
                    new_path = list(current)
                    new_path.append(next)
                    frontier.append(new_path)
                    came_from[next] = current[-1]
        if goal not in came_from:
            return None
        path = []
        current = goal
        while current != start:
            path.append(current)
            current = came_from[current]
        path.append(start)
        if path[-1] != goal:
            return None
        return path
    return a_star_search(graph, start, goal)

